import { createIntegrationsPlugin as createRuntimeIntegrationsPlugin, discordAdapter as createRuntimeDiscordAdapter, emailAdapter as createRuntimeEmailAdapter, googleDocsAdapter as createRuntimeGoogleDocsAdapter, microsoftTeamsAdapter as createRuntimeMicrosoftTeamsAdapter, slackAdapter as createRuntimeSlackAdapter, telegramAdapter as createRuntimeTelegramAdapter, whatsappAdapter as createRuntimeWhatsappAdapter, } from "@agent-native/core/integrations/runtime";
